CREATE FUNCTION cmd_validate_trade_work_start() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE w camp_trade_work_week%ROWTYPE; level integer; BEGIN SELECT * INTO STRICT w FROM camp_trade_work_week WHERE work_week_id=NEW.work_week_id; SELECT skill_level INTO level FROM actor_skill WHERE actor_id=w.actor_id AND skill_rule_id=w.skill_rule_id; IF w.source_command_id<>NEW.command_id OR level IS NULL OR level<>NEW.skill_level THEN RAISE EXCEPTION 'Trade work start snapshot mismatch'; END IF; RETURN NEW; END $$;
CREATE TRIGGER cmd_trade_work_start_valid BEFORE INSERT ON cmd_trade_work_start_receipt FOR EACH ROW EXECUTE FUNCTION cmd_validate_trade_work_start();
CREATE FUNCTION cmd_validate_trade_work_complete() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE w camp_trade_work_week%ROWTYPE; positive_count integer; negative_count integer; BEGIN SELECT * INTO STRICT w FROM camp_trade_work_week WHERE work_week_id=NEW.work_week_id; SELECT count(*) FILTER(WHERE account_id=w.worker_account_id AND amount_minor=250),count(*) FILTER(WHERE account_id=w.employer_account_id AND amount_minor=-250) INTO positive_count,negative_count FROM fin_entry WHERE transaction_id=NEW.payment_transaction_id; IF w.completion_command_id<>NEW.command_id OR w.payment_transaction_id<>NEW.payment_transaction_id OR NEW.wage_credits<>(SELECT adjudicated_weekly_credits FROM rule_trade_work_policy) OR positive_count<>1 OR negative_count<>1 OR (SELECT transaction_status FROM fin_transaction WHERE transaction_id=NEW.payment_transaction_id)<>'posted' THEN RAISE EXCEPTION 'Trade work completion or payment mismatch'; END IF; RETURN NEW; END $$;
CREATE TRIGGER cmd_trade_work_complete_valid BEFORE INSERT ON cmd_trade_work_complete_receipt FOR EACH ROW EXECUTE FUNCTION cmd_validate_trade_work_complete();
